-- SafetyTraining v20.050c
-- Reconcile live work-at-height / category III PPE completion-v2 material.
-- The 8h duration is an internal/legacy catalog allocation, not a universal statutory minimum.

DO $do$
DECLARE r jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"key":"height:hierarchy","title":"Lavoro in quota: scelta delle misure e gerarchia di protezione","summary":"Scegliere la soluzione partendo dall’eliminazione o riduzione del lavoro in quota e dalla protezione collettiva.","practical":false,"case":"Per una manutenzione breve su copertura confrontare parapetto temporaneo, PLE e sistema individuale, motivando vantaggi, limiti e recupero.","detail":"Prima del DPI individuale viene la progettazione del lavoro: evitare il lavoro in quota se possibile, scegliere accessi e piani di lavoro sicuri, privilegiare parapetti e altre protezioni collettive e usare sistemi individuali quando il rischio residuo lo richiede. Il corsista deve saper motivare perché una soluzione è preferibile a un’altra.","procedure":["definire attività, quota, durata e frequenza","valutare protezioni collettive e accesso sicuro","identificare rischio residuo e sistema individuale necessario","pianificare area sottostante, oggetti cadenti e soccorso"],"errors":["scegliere subito un’imbracatura senza valutare alternative","confondere accesso con postazione di lavoro","ignorare persone sotto la zona","pensare che il DPI elimini il rischio di caduta"]},
    {"key":"height:systems","title":"Trattenuta, posizionamento e arresto caduta: sistemi e limiti","summary":"Distinguere le funzioni dei sistemi individuali e scegliere quello coerente con il lavoro.","practical":false,"case":"Dato un bordo raggiungibile, progettare prima una soluzione di trattenuta e confrontarla con un arresto caduta.","detail":"La trattenuta impedisce di raggiungere la zona di caduta; il posizionamento sostiene l’operatore nel lavoro ma può richiedere protezione aggiuntiva; l’arresto caduta interviene dopo l’inizio della caduta e richiede spazio libero e componenti compatibili. Confondere le funzioni produce configurazioni inefficaci o pericolose.","procedure":["definire quale evento il sistema deve prevenire o arrestare","identificare imbracatura, collegamento e ancoraggio compatibili","considerare spazio libero e ostacoli","verificare istruzioni e limiti dei componenti come sistema"],"errors":["usare una cintura di posizionamento come arresto caduta","combinare componenti senza verificarne compatibilità","considerare tutti i cordini equivalenti","ignorare pendolo e ostacoli laterali"]},
    {"key":"height:inspection","title":"Imbracature, connettori, cordini e dispositivi: controllo pre-uso","summary":"Riconoscere componenti, marcature, difetti e criteri di ritiro dall’uso.","practical":true,"case":"Il docente prepara DPI integri e campioni fuori servizio: il corsista identifica difetti e decide quali non devono tornare all’uso.","detail":"Il controllo prima dell’uso non sostituisce l’ispezione periodica prevista dal fabbricante. Si esaminano tessili, cuciture, parti metalliche, connettori, assorbitore, dispositivi e marcature. Se esiste dubbio sull’integrità o il dispositivo ha subito un evento rilevante, viene ritirato e gestito secondo istruzioni.","procedure":["identificare dispositivo e istruzioni","controllare abrasioni, tagli, cuciture, deformazioni, corrosione e chiusure","verificare chiusura e blocco dei connettori","ritirare dal servizio un dispositivo dubbio o coinvolto in una caduta secondo procedura"],"errors":["segnare tessili con metodi non autorizzati","usare un DPI perché “sembra buono” dopo una caduta","confondere controllo utente e ispezione competente","mescolare componenti solo perché fisicamente collegabili"]},
    {"key":"height:anchors-clearance","title":"Ancoraggi, tirante d’aria, pendolo e percorso di caduta","summary":"Comprendere come posizione dell’ancoraggio e geometria influenzano conseguenze e fattibilità del sistema.","practical":false,"case":"Confrontare tre punti su uno schema e individuare quelli che introducono maggiore caduta, pendolo o ostacoli.","detail":"Il punto di ancoraggio non si sceglie perché è comodo. Deve essere previsto o valutato per lo scopo e collegato a un sistema coerente. Un ancoraggio basso può aumentare caduta e spazio necessario; uno laterale può creare pendolo. Il corsista riconosce il problema e procede solo con configurazioni definite da valutazione/procedura, senza improvvisare calcoli strutturali.","procedure":["usare solo punti previsti e identificati","mantenere il collegamento secondo la configurazione stabilita","valutare ostacoli e spazio libero disponibile","interrompere se punto o configurazione non sono chiaramente definiti"],"errors":["ancorarsi a parapetti o tubazioni non previsti","scegliere il punto più vicino senza valutarne funzione","ignorare il rischio pendolo","improvvisare un ancoraggio perché “sembra robusto”"]},
    {"key":"height:donning","title":"Vestizione, regolazione e prova dei DPI","summary":"Indossare e regolare correttamente l’imbracatura e collegare i componenti previsti.","practical":true,"case":"Ogni corsista controlla, indossa e regola il sistema e spiega quali punti di attacco sono utilizzabili nella configurazione proposta.","detail":"L’addestramento individuale verifica orientamento dell’imbracatura, regolazioni, fibbie, punti di attacco e compatibilità con altri DPI. Un’imbracatura troppo lenta o indossata in modo errato può aggravare le conseguenze di una caduta. Ogni corsista esegue personalmente controllo, vestizione e collegamento con feedback.","procedure":["eseguire controllo pre-uso","individuare correttamente punti di attacco previsti","regolare cinghie evitando torsioni","chiudere e verificare fibbie","eseguire controllo finale personale e del compagno/docente"],"errors":["lasciare cinghie attorcigliate","collegarsi a un anello non previsto per arresto caduta","regolare senza seguire istruzioni","saltare il controllo dopo cambio utilizzatore"]},
    {"key":"height:movement","title":"Movimento protetto, transizioni e mantenimento del collegamento","summary":"Esercitare spostamenti e cambi di punto senza creare intervalli non protetti.","practical":true,"case":"Percorso didattico con due transizioni: verbalizzare quale collegamento mantiene la protezione in ogni fase e la condizione di stop.","detail":"Il docente prepara una struttura didattica sicura a bassa esposizione e sistemi di backup coerenti. Il corsista mantiene il collegamento previsto, gestisce connettori e cambi di punto senza aperture simultanee non consentite, evita aggrovigliamenti e si ferma quando la progressione non è possibile nella configurazione prevista.","procedure":["pianificare la sequenza prima di muoversi","mantenere la protezione continua prevista","gestire un connettore alla volta quando la configurazione lo richiede","controllare che il collegamento non attraversi spigoli o organi pericolosi","tornare indietro o fermarsi se manca un punto previsto"],"errors":["sganciarsi per raggiungere un punto più comodamente","lasciare connettori in posizione che può favorirne apertura","far passare cordini su spigoli non previsti","proseguire oltre il sistema pianificato"]},
    {"key":"height:work-scenario","title":"Scenario operativo: accesso, lavoro, interferenze e chiusura","summary":"Integrare scelta dei sistemi, controllo area, accesso e svolgimento del compito.","practical":true,"case":"Scenario di manutenzione simulata in quota con una interferenza introdotta dal docente: adattarsi solo entro la procedura oppure fermarsi.","detail":"La prova integra briefing, delimitazione area sottostante, verifica ambiente/meteo, controllo DPI, accesso, posizionamento, gestione attrezzi, comunicazione e rientro. Il docente introduce un cambiamento controllato per verificare se il corsista si ferma invece di improvvisare.","procedure":["preparare area e piano prima della salita","controllare DPI e punti previsti","gestire attrezzi e materiali contro la caduta ove necessario","comunicare cambiamenti e interrompere se il piano non è più applicabile","rientrare e gestire/ispezionare i DPI dopo il lavoro"],"errors":["iniziare la salita prima di delimitare l’area","portare oggetti sciolti non gestiti","cambiare percorso senza rivalutazione","riporre DPI bagnati o sporchi senza gestione prevista"]},
    {"key":"height:rescue","title":"Sospensione, emergenza e piano di recupero","summary":"Comprendere perché il lavoro non può iniziare senza una strategia di recupero coerente.","practical":true,"case":"Simulazione a terra o bassa esposizione: persona “sospesa”; attivare piano, comunicare informazioni e identificare chi può eseguire il recupero.","detail":"Un lavoratore arrestato dal sistema può restare sospeso e necessitare di recupero rapido da personale addestrato. Chiamare i soccorsi è essenziale ma può non essere sufficiente come unico piano operativo. L’organizzazione predispone procedure, attrezzature e competenze compatibili con il sito. Tecniche specialistiche di soccorso si eseguono solo se specificamente addestrati.","procedure":["prima del lavoro identificare modalità e risorse di soccorso","in emergenza fermare attività e proteggere area","allertare immediatamente risorse previste e sistema di emergenza","non improvvisare recuperi per cui non si è addestrati","dopo un evento ritirare DPI coinvolti e riesaminare il sistema"],"errors":["considerare il 112/118 l’unico piano senza valutare accessibilità e tempi","fare un recupero tecnico senza formazione","rimettere in servizio DPI che hanno arrestato una caduta senza verifica","iniziare da soli quando il piano richiede assistenza"]}
  ]::jsonb) LOOP
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'key',r->>'title',r->>'summary',60,'SafetyTraining completion-v2',array['safetytraining','work-at-height','dpi3','completion-v2'],true,
      jsonb_build_object('learner_ready',true,'teacher_ready',true,'practical_focus',(r->>'practical')::boolean,'didactic_version','completion-v2'))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=60,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;

    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    VALUES(v_lu,1,'draft',jsonb_build_object(
      'case',r->>'case','norm','D.Lgs. 81/2008 artt. 77, 107, 111 e 115, ove applicabili; istruzioni dei fabbricanti e procedure aziendali. Le 8 ore sono la configurazione didattica SafetyTraining/legacy del corso, non una durata universale imposta dall’art. 77.',
      'quiz',jsonb_build_object('options',jsonb_build_array('Improvvisare un punto vicino','Proseguire con maggiore cautela','Fermarsi e far definire/ripristinare una soluzione prevista e verificata','Ridurre il tempo in quota'),'question','Se il sistema previsto non può essere applicato nella configurazione reale, qual è la scelta corretta?','explanation','Il tempo ridotto o la maggiore attenzione non rendono idoneo un sistema diverso da quello valutato e previsto.','correct_index',2),
      'title',r->>'title','detail',r->>'detail','minutes',60,'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',(r->>'practical')::boolean),'summary',r->>'summary',
      'visuals',jsonb_build_array('piramide-pericoli.svg','procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg'),'procedure',r->'procedure','common_errors',r->'errors',
      'delivery_note','Tutto il materiale è consultabile; l’addestramento effettivo sui DPI di III categoria resta attività pratica e non è sostituito dalla fruizione digitale.',
      'guided_activity',jsonb_build_array('spiegazione con esempio reale','analisi di una configurazione corretta e una errata','esercizio individuale o scenario decisionale','feedback su rischio, barriera e stop'),
      'didactic_version','completion-v2','final_assessment',false,
      'teacher_expansion',case when (r->>'practical')::boolean then 'Eseguire addestramento individuale con DPI e configurazioni coerenti con istruzioni del fabbricante e procedura. Usare strutture didattiche controllate e sistemi di backup quando necessario. Il docente osserva controllo, vestizione, collegamento, decisioni e criterio di stop.' else 'Usare schemi, fotografie tecniche e casi di lavoro reali. Chiedere sempre di confrontare protezione collettiva e individuale, funzione del sistema, possibili ostacoli e piano di soccorso. Evitare di trasformare l’esercizio in progettazione strutturale non supportata.' end),null)
    ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;

    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
    VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}')
    ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
  END LOOP;

  SELECT id INTO v_course FROM public.courses WHERE stable_key='lav_quota';
  UPDATE public.courses SET title='Lavori in quota e DPI III categoria - 8h',family='Rischi specialistici',description='Percorso SafetyManager da 8h per lavori in quota e DPI III categoria. La durata di 8h è una scelta di catalogo e non è registrata come minimo nazionale dell’art. 77; l’addestramento pratico resta obbligatorio.',nominal_minutes=480,active=true,
    metadata=metadata||'{"blueprint_key":"work_height_dpi3","duration_source":"safetymanager_legacy_catalog","didactic_version":"completion-v2","material_complete":true,"composition_version":"v20_030","delivery_constraint":"physical_only","requires_admin_review":true,"learner_catalog_hidden":true,"learner_material_complete":true,"teacher_material_complete":true,"internal_didactic_allocation":true,"practical_component_separate":true,"statutory_total_duration_claim":false,"delivery_rules_are_metadata_only":true}'::jsonb,updated_at=now() WHERE id=v_course;
  SELECT id INTO v_cv FROM public.course_versions WHERE course_id=v_course AND version_number=1;
  UPDATE public.course_versions SET status='draft',effective_from=date '2025-05-24',published_at=null,
    syllabus_snapshot='{"source":"v20_030","blueprint_key":"work_height_dpi3","duration_note":"8h SafetyTraining legacy/internal course allocation; not asserted as universal statutory minimum","nominal_minutes":480,"didactic_version":"completion-v2","material_minutes":480,"material_complete":true,"learning_unit_count":8}'::jsonb,
    normative_snapshot='{"reference":"D.Lgs. 81/2008 art. 77","publication_gate":"Admin/didactic review + practical validation"}'::jsonb WHERE id=v_cv;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes)
  VALUES(v_cv,'height-dpi3','Lavori in quota e DPI anticaduta: teoria operativa e addestramento',1,480)
  ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=1,nominal_minutes=480 RETURNING id INTO v_module;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"k":"height:hierarchy","p":1,"g":false},{"k":"height:systems","p":2,"g":false},{"k":"height:inspection","p":3,"g":true},{"k":"height:anchors-clearance","p":4,"g":false},{"k":"height:donning","p":5,"g":true},{"k":"height:movement","p":6,"g":true},{"k":"height:work-scenario","p":7,"g":true},{"k":"height:rescue","p":8,"g":true}]'::jsonb) LOOP
    SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k';
    INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>'g')::boolean))
    ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules;
  END LOOP;
  INSERT INTO public.course_practical_requirements(course_id,requirement_key,title,nominal_minutes,required,completion_mode,metadata)
  VALUES(v_course,'dpi3_training','Addestramento pratico DPI III categoria',240,true,'external_presence','{"duration_source":"legacy_catalog_not_statutory","allocation_minutes_internal":true,"statutory_training_required":true}'::jsonb)
  ON CONFLICT(course_id,requirement_key) DO UPDATE SET title=excluded.title,nominal_minutes=240,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();
END $do$;
